            for (int kd = 0; kd < Kd; ++kd) {
                const int nd = od + pd - kd;
                if (nd < 0 || (nd % sd) != 0) continue;
                const int id = nd / sd;
                if (id < 0 || id >= Din) continue;

                for (int kh = 0; kh < Kh; ++kh) {
                    const int nh = oh + ph - kh;
                    if (nh < 0 || (nh % sh) != 0) continue;
                    const int ih = nh / sh;
                    if (ih < 0 || ih >= Hin) continue;

                    for (int kw = 0; kw < Kw; ++kw) {
                        const int nw = ow + pw - kw;
                        if (nw < 0 || (nw % sw) != 0) continue;
                        const int iw = nw / sw;
                        if (iw < 0 || iw >= Win) continue;

                        const float xv = x[((((size_t)n * Cin + ci) * Din + id) * Hin + ih) * Win + iw];
                        const float wv = w[((((size_t)ci * out_per + co_rel) * Kd + kd) * Kh + kh) * Kw + kw];
                        sum += xv * wv;
                    }
                }
            }
        }

        y[((((size_t)n * Cout + co) * Dout + od) * Hout + oh) * Wout + ow] = sum;
    }
}

torch::Tensor conv_transpose3d_forward(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    bool has_bias,
    int64_t sd, int64_t sh, int64_t sw,
    int64_t pd, int64_t ph, int64_t pw,
    int64_t od, int64_t oh, int64_t ow,
    int64_t groups)
